"use strict";let loaded_sources=[],loading_sources={};const require={js:async function(e,s){if("undefined"!=typeof $){$.isArray(e)||(e=[e]);try{for(const s of e)loading_sources[s]?await loading_sources[s]:-1===$.inArray(s,loaded_sources)&&(loading_sources[s]=$.getScript(s).then(function(){loaded_sources.push(s),delete loading_sources[s]}),await loading_sources[s]);"function"==typeof s&&s()}catch(e){console.error("[require.js] failed to load script:",e)}}else console.log("jQuery is required to use require.js()")},css:async function(e,s){"undefined"!=typeof $?($.isArray(e)||(e=[e]),e.forEach(function(e){-1===$.inArray(e,loaded_sources)&&(loaded_sources.push(e),$(`<link rel="stylesheet" type="text/css" href="${e}" />`).appendTo("head"))}),"function"==typeof s&&s()):console.log("jQuery is required to use require.css()")}};